css:
:root {
    --primary-color: lightseagreen;
    --secondary-color: lightgray;
    --background-color: whitesmoke;
    --text-color: white;
}

body {
    background-color: var(--primary-color);
    font-family: Arial, Helvetica, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
    height: 100vh;
    margin: 0;
}

#password-generator {
    background-color: var(--background-color);
    border: 5px solid var(--secondary-color);
    width: 90%;
    max-width: 500px;
    padding: 20px;
    border-radius: 25px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

#password {
    display: grid;
    grid-template-columns: 1fr min-content;
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 15px;
}

#result {
    padding: 10px;
    background-color: var(--secondary-color);
    font-size: 1.2em;
    border: none;
    outline: none;
    width: 100%;
}

#copy-button {
    background-color: var(--primary-color);
    color: var(--text-color);
    padding: 10px;
    border: none;
    cursor: pointer;
    transition: background-color 0.3s;
}

#copy-button:hover {
    background-color: darken(var(--primary-color), 10%);
    color: black;
    border: 1px solid blue;
    border-left: none;
}

#password-length {
    width: 100%;
    margin: 10px 0;
}

#options {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
    margin: 15px 0;
}

#options label {
    display: flex;
    align-items: center;
    background-color: var(--secondary-color);
    padding: 10px;
    border-radius: 10px;
    cursor: pointer;
    font-family: sans-serif;
}

#generate-button {
    background-color: var(--primary-color);
    color: var(--text-color);
    border: none;
    border-radius: 10px;
    padding: 10px;
    width: 100%;
    font-size: 1em;
    cursor: pointer;
    transition: background-color 0.3s;
}

#generate-button:hover {
    background-color: darken(var(--primary-color), 10%);
    color: black;
    border: 1px solid blue;
}

